const makePost = (topic: Topic, index: number): BlogPost => ({
  slug: topic.slug,
  sourceSegment: `Campaign date 2026-09-03. Visible publication date September 3, 2026. Route-local source for ${topic.slug}: ${topic.sections.join(' ')} ${topic.faqs.join(' ')}`,
  title: topic.title,
  excerpt: topic.excerpt,
  minutes: 11 + index % 4,
  keyword: topic.title,
  published: '2026-09-03',
  updated: '2026-09-03',
  intro: `${topic.excerpt} ${topic.question} ${additionalIntro[topic.slug] ?? ''}`.trim(),
  sections: topic.sections.map((body, n) => ({ title: sectionHeadings[topic.slug][n], paragraphs: [body] })),
  faqs: [{ question: topic.faqs[0], answer: topic.faqs[1] }, { question: topic.faqs[2], answer: topic.faqs[3] }, { question: topic.faqs[4], answer: topic.faqs[5] }],
});

export const september3BlogBatch: readonly BlogPost[] = topics.slice(0, 12).map(makePost);
